// GENERATED by scripts/sync-shared.mjs from shared/. Do not edit here.
// SOURCE FILE. Edit here, then run `npm run sync` to copy into src/app/cards.
// Matrix prices, laid out like Utility Click's Instant Quote: one meter's details, up to five
// durations, Generate Prices, then every product that can quote. Fields are prefilled from the
// meters on the deal; pick another meter to quote it.
import React, { useEffect, useMemo, useState } from 'react';
import {
  Accordion, Alert, Box, Button, Checkbox, DateInput, Divider, Flex, Heading, Input, LoadingSpinner, NumberInput,
  Select, Table, TableBody, TableCell, TableHead, TableHeader, TableRow, Tag, Text, Tile, ToggleGroup, hubspot,
} from '@hubspot/ui-extensions';

type Fuel = 'E' | 'G' | 'HH';
type Meter = {
  id: string; meterNumber: string; fuel: Fuel; region: string | null; profile: string | null; rateType: string;
  band: string | null; aq: number; dayShare: number | null; kva: number | null; voltage: string | null; exitZone: string | null;
  start: string | null; current: string | null; notes: string[];
};
type Book = { fuel: string; supplier: string; quoteBy: string | null };
type Ctx = { dealName: string; meters: Meter[]; books: Book[]; stipulated?: string[]; booksError: string | null; notes: string[]; error?: string };
type Option = {
  supplier: string; products: string[]; term: number; endDate: string | null; green: boolean;
  rates: { unit: number | null; day: number | null; night: number | null; ew: number | null };
  sc: number; kvaCharge: number | null; capacityMissingKva: boolean; annual: number; commission: number; totalComms: number;
  quoteBy: string | null; expired: boolean; splitAssumed: boolean;
};
type MeterResult = { meterId: string; errors: string[]; options: Option[]; truncated?: boolean; missing: { supplier: string; reason: string }[] };
type PriceResponse = { today: string; results: MeterResult[]; error?: string };
type DateVal = { year: number; month: number; date: number };
type Form = {
  meterId: string; site: string; meterNumber: string; fuel: Fuel; region: string; aq: number | null; company: string;
  start: string | null; commission: number | null; useSc: boolean; scCommission: number | null;
  profile: string; rateType: string; band: string; dayShare: number | null; kva: number | null; voltage: string;
  exitZone: string; current: string | null; dd: string; amr: string;
};

const UTILITIES = [
  { value: 'G', label: 'Gas' },
  { value: 'E', label: 'Non Half Hourly Electric' },
  { value: 'HH', label: 'Half Hourly Electric' },
];
const DNO: Record<string, string> = {
  10: 'Eastern', 11: 'East Midlands', 12: 'London', 13: 'Merseyside & N Wales', 14: 'Midlands', 15: 'Northern', 16: 'North Western',
  17: 'North Scotland', 18: 'South Scotland', 19: 'South Eastern', 20: 'Southern', 21: 'South Wales', 22: 'South Western', 23: 'Yorkshire',
};
const LDZ = ['EA', 'EM', 'NE', 'NO', 'NT', 'NW', 'SC', 'SE', 'SO', 'SW', 'WM', 'WN', 'WS'];
const PROFILES = ['01', '02', '03', '04', '05', '06', '07', '08'].map((v) => ({ value: v, label: `Profile class ${v}` }));
const RATES = [
  { value: 'single', label: 'Single rate' }, { value: 'daynight', label: 'Day/night (Economy 7)' },
  { value: 'ew', label: 'Evening/weekend' }, { value: 'ewn', label: 'Evening/weekend/night' },
];
const VOLTAGES = ['Low voltage', 'LV substation', 'LV network non-CT', 'High voltage'].map((v) => ({ value: v, label: v }));
const BANDS = ['1', '2', '3', '4'].map((v) => ({ value: v, label: `Band ${v}` }));
const YNA = [{ value: 'any', label: 'Any' }, { value: 'yes', label: 'Yes' }, { value: 'no', label: 'No' }];
const MAX_DURATIONS = 5;

const gbp = (v: number) => v.toLocaleString('en-GB', { style: 'currency', currency: 'GBP', maximumFractionDigits: 0 });
const p = (v: number | null) => (v == null ? '-' : `${v.toFixed(3)}p`);
const uk = (iso: string | null) => (iso ? iso.split('-').reverse().join('/') : '');
const toDate = (iso: string | null): DateVal | undefined => { if (!iso) return undefined; const [y, m, d] = iso.split('-').map(Number); return { year: y, month: m - 1, date: d }; };
const fromDate = (v: DateVal | null) => (v ? `${v.year}-${String(v.month + 1).padStart(2, '0')}-${String(v.date).padStart(2, '0')}` : null);
const yn = (v: string) => (v === 'yes' ? true : v === 'no' ? false : null);
const unwrap = <T,>(r: unknown): T => ((r as { body?: T })?.body ?? r) as T;
// "BLACK ORANGE INV LTD - RENEWALS" -> "BLACK ORANGE INV LTD"
const companyFrom = (dealName: string) => dealName.split(' - ')[0].trim();

const formFrom = (m: Meter | null, company: string): Form => ({
  meterId: m?.id || 'manual', site: '', meterNumber: m?.meterNumber || '', fuel: m?.fuel || 'E',
  region: m?.region || '', aq: m?.aq || null, company,
  start: m?.start || null, commission: null, useSc: false, scCommission: null,
  profile: m?.profile || '', rateType: m?.rateType && m.rateType !== 'hh' ? m.rateType : 'single', band: m?.band || '1',
  dayShare: m?.dayShare ?? null, kva: m?.kva ?? null, voltage: m?.voltage || '', exitZone: m?.exitZone || '',
  current: m?.current || null, dd: 'any', amr: 'any',
});

// A full MPAN (top line + core, 21 digits) gives the profile class and region; the 13-digit core gives the region.
const fromMpan = (num: string) => {
  const d = num.replace(/\D/g, '');
  if (d.length === 21) return { profile: d.slice(0, 2), region: d.slice(8, 10) };
  if (d.length === 13) return { profile: null, region: d.slice(0, 2) };
  return { profile: null, region: null };
};

// Utility Click style row: label on the left, field on the right.
const Row = ({ label, required, children }: { label: string; required?: boolean; children: React.ReactNode }) => (
  <Flex direction="row" align="center" gap="md">
    <Box flex={1}><Text format={{ fontWeight: 'demibold' }}>{label}{required ? ' *' : ''}</Text></Box>
    <Box flex={2}>{children}</Box>
  </Flex>
);
const WithUnit = ({ unit, children }: { unit: string; children: React.ReactNode }) => (
  <Flex direction="row" align="center" gap="xs">
    <Box flex={1}>{children}</Box>
    <Text>{unit}</Text>
  </Flex>
);

export const MatrixPricing = ({ dealId }: { dealId?: string | null }) => {
  const [ctx, setCtx] = useState<Ctx | null>(null);
  const [form, setForm] = useState<Form>(formFrom(null, ''));
  const [durations, setDurations] = useState<(number | null)[]>([12, 24, 36]);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [res, setRes] = useState<MeterResult | null>(null);
  const [view, setView] = useState('all');
  const [saveMsg, setSaveMsg] = useState<{ ok: boolean; text: string } | null>(null);

  useEffect(() => {
    if (!dealId) return;
    (async () => {
      try {
        const c = unwrap<Ctx>(await hubspot.serverless('matrix_deal_context', { parameters: { dealId } }));
        if (c.error) { setErr(c.error); return; }
        setCtx(c);
        setForm(formFrom(c.meters[0] || null, companyFrom(c.dealName)));
      } catch (e) { setErr(`Couldn't read the deal: ${(e as Error).message}`); }
    })();
  }, [dealId]);

  const set = (patch: Partial<Form>) => setForm((f) => ({ ...f, ...patch }));
  const suppliers = useMemo(() => [...new Set((ctx?.books || []).filter((b) => b.fuel === form.fuel).map((b) => b.supplier))].sort(), [ctx, form.fuel]);
  const uncapped = suppliers.filter((s) => !(ctx?.stipulated || []).includes(s));
  const meterOptions = [
    ...(ctx?.meters || []).map((m) => ({ value: m.id, label: `${m.meterNumber || m.id} · ${UTILITIES.find((u) => u.value === m.fuel)?.label}` })),
    { value: 'manual', label: 'Enter details manually' },
  ];
  const chosen = ctx?.meters.find((m) => m.id === form.meterId) || null;
  const terms = [...new Set(durations.filter((d): d is number => !!d && d > 0))].sort((a, b) => a - b);

  const pickMeter = (id: string) => {
    const m = ctx?.meters.find((x) => x.id === id) || null;
    setForm(formFrom(m, form.company)); setRes(null); setSaveMsg(null);
  };
  const setMeterNumber = (v: string) => {
    const got = fromMpan(v);
    set({ meterNumber: v, ...(got.region && form.fuel !== 'G' ? { region: got.region } : {}), ...(got.profile ? { profile: got.profile } : {}) });
  };
  const cancel = () => { setForm(formFrom(chosen, companyFrom(ctx?.dealName || ''))); setDurations([12, 24, 36]); setRes(null); setErr(null); setSaveMsg(null); };

  const generate = async () => {
    setBusy(true); setErr(null); setSaveMsg(null); setRes(null);
    try {
      const meter = {
        id: form.meterId, meterNumber: form.meterNumber, fuel: form.fuel, region: form.region || null,
        profile: form.fuel === 'E' ? form.profile || null : null,
        rateType: form.fuel === 'HH' ? 'hh' : form.fuel === 'G' ? 'single' : form.rateType,
        band: form.fuel === 'G' ? null : form.band, aq: form.aq || 0, dayShare: form.dayShare,
        kva: form.fuel === 'HH' ? form.kva : null, voltage: form.fuel === 'HH' ? form.voltage || null : null,
        exitZone: form.fuel === 'G' ? form.exitZone || null : null, start: form.start, current: form.current, notes: [],
      };
      const all = (v: number | null) => (v == null ? {} : Object.fromEntries(suppliers.map((s) => [s, v])));
      const r = unwrap<PriceResponse>(await hubspot.serverless('matrix_price', {
        parameters: {
          meters: [meter], terms, commission: all(form.commission),
          scCommission: form.useSc ? all(form.scCommission) : {}, dd: yn(form.dd), amr: yn(form.amr),
        },
      }));
      if (r.error) setErr(r.error); else { setRes(r.results[0] || null); setView('all'); }
    } catch (e) { setErr(`Couldn't generate prices: ${(e as Error).message}`); }
    setBusy(false);
  };

  const save = async (o: Option) => {
    setSaveMsg(null);
    try {
      const out = unwrap<{ saved?: boolean; error?: string }>(await hubspot.serverless('stip_save_estimate', {
        parameters: { dealId, supplier: o.supplier, product: o.products.join(' / '), comms: o.commission, term: o.term, annual: ((form.aq || 0) * o.commission) / 100, total: o.totalComms },
      }));
      setSaveMsg(out.saved ? { ok: true, text: `Saved ${o.supplier} ${o.products[0]}, ${o.term} months, ${gbp(o.totalComms)} commission, to this deal.` } : { ok: false, text: out.error || "Couldn't save to the deal." });
    } catch (e) { setSaveMsg({ ok: false, text: `Couldn't save to the deal: ${(e as Error).message}` }); }
  };

  if (!ctx && !err) return <LoadingSpinner label="Reading the deal's meters" />;

  const missingRequired = [
    !form.region && (form.fuel === 'G' ? 'gas zone (LDZ)' : 'distributor (area code)'),
    !(form.aq && form.aq > 0) && 'annual consumption',
    !form.company && 'company name',
    !form.start && 'contract start date',
    !terms.length && 'a duration',
  ].filter(Boolean) as string[];
  const opts = (res?.options || []).filter((o) => view === 'all' || String(o.term) === view);
  const showRates = {
    unit: opts.some((o) => o.rates.unit != null), day: opts.some((o) => o.rates.day != null),
    night: opts.some((o) => o.rates.night != null), ew: opts.some((o) => o.rates.ew != null),
  };

  return (
    <Flex direction="column" gap="md">
      {err && <Alert title="Something went wrong" variant="error">{err}</Alert>}
      {ctx?.booksError && <Alert title="Price books" variant="warning">{ctx.booksError}</Alert>}
      {ctx && (
        <>
          <Heading>Instant Quote</Heading>
          <Text variant="microcopy">
            {suppliers.length ? `Live price books for this utility: ${suppliers.join(', ')}. Prices exclude CCL and VAT.` : 'No price books are loaded for this utility yet.'}
          </Text>

          <Tile>
            <Flex direction="column" gap="sm">
              <Row label="Meter on this deal">
                <Select name="meter" label="" options={meterOptions} value={form.meterId} onChange={(v) => pickMeter(String(v))} />
              </Row>
              {chosen?.notes.map((n) => <Tag key={n} variant="warning">{n}</Tag>)}
              <Divider />
              <Text>Enter meter details provided by your customer</Text>
              <Row label="Site Address">
                <Input name="site" label="" value={form.site} onChange={(v) => set({ site: v })} />
              </Row>
              <Row label="Meter Number">
                <Input name="meterNumber" label="" value={form.meterNumber} onChange={setMeterNumber} />
              </Row>
              <Row label="Utility" required>
                <ToggleGroup name="utility" label="" toggleType="radioButtonList" options={UTILITIES} value={form.fuel}
                  onChange={(v: string) => set({ fuel: v as Fuel, region: '' })} />
              </Row>
              {form.fuel === 'G' ? (
                <Row label="Gas Zone (LDZ)" required>
                  <Select name="ldz" label="" options={LDZ.map((z) => ({ value: z, label: z }))} value={form.region} onChange={(v) => set({ region: String(v) })} />
                </Row>
              ) : (
                <Row label="Distributor (Area Code)" required>
                  <Select name="region" label="" options={Object.entries(DNO).map(([k, n]) => ({ value: k, label: `${k} - ${n}` }))} value={form.region} onChange={(v) => set({ region: String(v) })} />
                </Row>
              )}
              <Row label="Annual Consumption" required>
                <WithUnit unit="kWh"><NumberInput name="aq" label="" min={0} value={form.aq ?? undefined} onChange={(v: number) => set({ aq: v })} /></WithUnit>
              </Row>
              <Row label="Company Name" required>
                <Input name="company" label="" value={form.company} onChange={(v) => set({ company: v })} />
              </Row>
              <Row label="Contract Start Date" required>
                <DateInput name="start" label="" format="L" value={toDate(form.start)} onChange={(v) => set({ start: fromDate(v as DateVal | null) })} />
              </Row>
              <Row label="Commission" required>
                <WithUnit unit="p/kWh">
                  <NumberInput name="commission" label="" precision={3} min={0} placeholder="Max allowed" value={form.commission ?? undefined} onChange={(v: number) => set({ commission: v })} />
                </WithUnit>
              </Row>
              <Row label="Use Standing Charge Commissions">
                <Checkbox name="useSc" checked={form.useSc} onChange={(v: boolean) => set({ useSc: v })} />
              </Row>
              {form.useSc && (
                <Row label="Standing Charge Commission">
                  <WithUnit unit="p/day"><NumberInput name="scCommission" label="" precision={2} min={0} value={form.scCommission ?? undefined} onChange={(v: number) => set({ scCommission: v })} /></WithUnit>
                </Row>
              )}
              <Text variant="microcopy">Leave commission blank to use each supplier's maximum from the stipulations. It's never set above that maximum.</Text>
              {form.commission == null && uncapped.length > 0 && (
                <Alert title="Commission needed" variant="warning">
                  {uncapped.join(', ')} {uncapped.length === 1 ? 'has' : 'have'} no stipulation, so there's no maximum to use. Enter a commission, or {uncapped.length === 1 ? 'its' : 'their'} prices will include none.
                </Alert>
              )}
              <Accordion title="More meter details" size="sm" defaultOpen={false}>
                <Flex direction="column" gap="sm">
                  {form.fuel === 'E' && (
                    <>
                      <Row label="Profile Class"><Select name="profile" label="" options={PROFILES} value={form.profile} onChange={(v) => set({ profile: String(v) })} /></Row>
                      <Row label="Meter Type"><Select name="rateType" label="" options={RATES} value={form.rateType} onChange={(v) => set({ rateType: String(v) })} /></Row>
                      {form.rateType !== 'single' && (
                        <Row label="Day Usage"><WithUnit unit="%"><NumberInput name="dayShare" label="" min={0} max={100} placeholder="75" value={form.dayShare ?? undefined} onChange={(v: number) => set({ dayShare: v })} /></WithUnit></Row>
                      )}
                    </>
                  )}
                  {form.fuel === 'HH' && (
                    <>
                      <Row label="Voltage"><Select name="voltage" label="" options={VOLTAGES} value={form.voltage} onChange={(v) => set({ voltage: String(v) })} /></Row>
                      <Row label="Capacity (kVA)"><NumberInput name="kva" label="" min={0} value={form.kva ?? undefined} onChange={(v: number) => set({ kva: v })} /></Row>
                      <Row label="Day Usage"><WithUnit unit="%"><NumberInput name="dayShareHh" label="" min={0} max={100} placeholder="75" value={form.dayShare ?? undefined} onChange={(v: number) => set({ dayShare: v })} /></WithUnit></Row>
                    </>
                  )}
                  {form.fuel !== 'G' && (
                    <Row label="Network Charging Band"><Select name="band" label="" options={BANDS} value={form.band} onChange={(v) => set({ band: String(v) })} /></Row>
                  )}
                  {form.fuel === 'G' && (
                    <Row label="Exit Zone"><Input name="exitZone" label="" value={form.exitZone} onChange={(v) => set({ exitZone: v.toUpperCase() })} /></Row>
                  )}
                  <Row label="Pays by Direct Debit"><Select name="dd" label="" options={YNA} value={form.dd} onChange={(v) => set({ dd: String(v) })} /></Row>
                  <Row label="Smart / AMR Meter"><Select name="amr" label="" options={YNA} value={form.amr} onChange={(v) => set({ amr: String(v) })} /></Row>
                </Flex>
              </Accordion>
            </Flex>
          </Tile>

          <Tile>
            <Flex direction="column" gap="sm">
              <Text>Choose up to five durations for pricing results.</Text>
              <Text format={{ fontWeight: 'demibold' }}>Duration *</Text>
              {durations.map((d, i) => (
                <Flex key={i} direction="row" align="center" gap="sm">
                  <Box flex={1}>
                    <WithUnit unit="Months">
                      <NumberInput name={`duration-${i}`} label="" min={1} max={120} value={d ?? undefined}
                        onChange={(v: number) => setDurations((ds) => ds.map((x, j) => (j === i ? v : x)))} />
                    </WithUnit>
                  </Box>
                  <Button variant="transparent" size="sm" onClick={() => setDurations((ds) => ds.filter((_, j) => j !== i))} disabled={durations.length === 1}>✕</Button>
                </Flex>
              ))}
              <Box>
                <Button onClick={() => setDurations((ds) => [...ds, null])} disabled={durations.length >= MAX_DURATIONS}>+ Add Duration</Button>
              </Box>
              <Text variant="microcopy">Fixed end date products (e.g. EOC) always show, priced to their end date.</Text>
            </Flex>
          </Tile>

          {missingRequired.length > 0 && <Text variant="microcopy">To generate prices, add the {missingRequired.join(', ')}.</Text>}
          <Flex direction="row" gap="sm">
            <Button onClick={cancel}>✕ Cancel</Button>
            <Button variant="primary" onClick={generate} disabled={busy || missingRequired.length > 0}>{busy ? 'Generating…' : '⚙ Generate Prices'}</Button>
          </Flex>
        </>
      )}

      {res && (
        <>
          <Divider />
          <Heading>Quote results</Heading>
          <Text>{form.company}{form.meterNumber ? ` · ${form.meterNumber}` : ''} · {UTILITIES.find((u) => u.value === form.fuel)?.label} · {(form.aq || 0).toLocaleString('en-GB')} kWh · from {uk(form.start)}</Text>
          {res.errors.map((e) => <Alert key={e} title="Can't price this meter yet" variant="warning">{e}</Alert>)}
          {!!res.options.length && (
            <Flex direction="row" align="center" justify="between" gap="sm">
              <Text format={{ fontWeight: 'demibold' }}>{res.options.length} quotes</Text>
              <Select name="view" label="" options={[{ value: 'all', label: 'All durations' }, ...[...new Set(res.options.map((o) => o.term))].sort((a, b) => a - b).map((t) => ({ value: String(t), label: `${t} months` }))]}
                value={view} onChange={(v) => setView(String(v))} />
            </Flex>
          )}
          {saveMsg && <Alert title={saveMsg.ok ? 'Saved' : "Couldn't save"} variant={saveMsg.ok ? 'success' : 'error'}>{saveMsg.text}</Alert>}
          {!!opts.length && (
            <Table bordered>
              <TableHead>
                <TableRow>
                  <TableHeader>Supplier</TableHeader>
                  <TableHeader>Annual Cost</TableHeader>
                  <TableHeader>Commission</TableHeader>
                  <TableHeader>Length</TableHeader>
                  {showRates.unit && <TableHeader>Unit</TableHeader>}
                  {showRates.day && <TableHeader>Day</TableHeader>}
                  {showRates.night && <TableHeader>Night</TableHeader>}
                  {showRates.ew && <TableHeader>Eve/Wkend</TableHeader>}
                  <TableHeader>Standing Charge</TableHeader>
                  <TableHeader>Save</TableHeader>
                </TableRow>
              </TableHead>
              <TableBody>
                {opts.map((o, i) => (
                  <TableRow key={`${o.supplier}-${i}`}>
                    <TableCell>
                      <Text format={{ fontWeight: 'demibold' }}>{o.supplier}</Text>
                      <Text variant="microcopy">{o.products.join(' / ')}</Text>
                      {o.green && <Tag variant="success">Green</Tag>}
                      {o.expired && <Tag variant="error">Out of date</Tag>}
                      {o.capacityMissingKva && <Tag variant="warning">No kVA</Tag>}
                    </TableCell>
                    <TableCell>{gbp(o.annual)}</TableCell>
                    <TableCell>{gbp(o.totalComms)}<Text variant="microcopy">{o.commission}p/kWh</Text></TableCell>
                    <TableCell>{o.endDate ? `Fixed to ${uk(o.endDate)}` : `${o.term} months`}</TableCell>
                    {showRates.unit && <TableCell>{p(o.rates.unit)}</TableCell>}
                    {showRates.day && <TableCell>{p(o.rates.day)}</TableCell>}
                    {showRates.night && <TableCell>{p(o.rates.night)}</TableCell>}
                    {showRates.ew && <TableCell>{p(o.rates.ew)}</TableCell>}
                    <TableCell>{o.sc ? `${o.sc.toFixed(2)}p/day` : 'None'}{o.kvaCharge ? ` + ${o.kvaCharge}p/kVA/m` : ''}</TableCell>
                    <TableCell><Button size="xs" onClick={() => save(o)} disabled={!dealId}>Save to deal</Button></TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
          {res.truncated && <Text variant="microcopy">Showing the cheapest 150 quotes.</Text>}
          {!!res.missing.length && (
            <>
              <Text format={{ fontWeight: 'demibold' }}>Not quoting</Text>
              {res.missing.map((x) => <Text key={x.supplier}>{x.supplier}: {x.reason}</Text>)}
            </>
          )}
          {res.options.some((o) => o.splitAssumed) && <Text variant="microcopy">Day/night split assumed 75/25. Set Day Usage under More meter details to change it.</Text>}
        </>
      )}
    </Flex>
  );
};
